<?php defined('ABSPATH')||exit;get_header();$cats=get_terms(['taxonomy'=>'bakery_product_category','hide_empty'=>false]);?><main id="main-content" class="section shell"><header class="archive-head"><p class="eyebrow">Frisch & vielfältig</p><h1>Unser Sortiment</h1><p>Alle Produkte stammen aus WordPress und können im Admin-Bereich bearbeitet werden.</p></header><form class="filters" method="get" data-product-filters><label>Produktsuche<input type="search" name="produkt_suche" value="<?php echo esc_attr(wp_unslash($_GET['produkt_suche']??''));?>"></label><label>Kategorie<select name="kategorie"><option value="">Alle Kategorien</option><?php foreach($cats as$c)printf('<option value="%s" %s>%s</option>',esc_attr($c->slug),selected($_GET['kategorie']??'',$c->slug,false),esc_html($c->name));?></select></label><label>Sortierung<select name="sort"><option value="title_asc" <?php selected($_GET['sort']??'','title_asc');?>>Name A–Z</option><option value="title_desc" <?php selected($_GET['sort']??'','title_desc');?>>Name Z–A</option><option value="price_asc" <?php selected($_GET['sort']??'','price_asc');?>>Preis aufsteigend</option><option value="price_desc" <?php selected($_GET['sort']??'','price_desc');?>>Preis absteigend</option></select></label><div class="filter-checks"><label><input type="checkbox" name="vegan" value="1" <?php checked(!empty($_GET['vegan']));?>> Vegan</label><label><input type="checkbox" name="vegetarian" value="1" <?php checked(!empty($_GET['vegetarian']));?>> Vegetarisch</label><label><input type="checkbox" name="seasonal" value="1" <?php checked(!empty($_GET['seasonal']));?>> Saisonal</label><label><input type="checkbox" name="available" value="1" <?php checked(!empty($_GET['available']));?>> Verfügbar</label></div><button class="button" type="submit">Filtern</button><a class="reset-link" href="<?php echo esc_url(get_post_type_archive_link('bakery_product'));?>">Filter zurücksetzen</a></form><p class="result-count" aria-live="polite"><?php global$wp_query;echo esc_html(sprintf(_n('%d Produkt','%d Produkte',$wp_query->found_posts,'morgenbrot'),$wp_query->found_posts));?></p><div class="card-grid products"><?php if(have_posts()):while(have_posts()):the_post();get_template_part('template-parts/product','card');endwhile;else:?><div class="empty"><h2>Keine Produkte gefunden</h2><p>Ändern Sie die Filter oder setzen Sie die Auswahl zurück.</p><a class="button" href="<?php echo esc_url(get_post_type_archive_link('bakery_product'));?>">Alle Produkte</a></div><?php endif;?></div><?php the_posts_pagination(array('prev_text'=>'← Zurück','next_text'=>'Weiter →'));?></main><?php get_footer();
